"""Build the examples website: run every example and publish its outputs.

Usage: python .github/scripts/build_examples_site.py OUTPUT_DIR

Each example runs in its own temporary copy of the repository's example
files, so nothing in the working tree changes. Its outputs (HTML, PDF,
Markdown, LaTeX and any image folders) are copied to OUTPUT_DIR/<slug>/, the
example's source to OUTPUT_DIR/<slug>/source.py, and an index page — built
with reportsmith itself — lists them all.
"""

from __future__ import annotations

import ast
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))  # the index page uses this checkout's reportsmith too
REPO_URL = "https://github.com/mstojke/reportsmith"

# (script relative to the repo root, slug, title), in gallery order. The
# description under each title is the first sentence of the script's docstring.
EXAMPLES = [
    ("example.py", "quick-start", "Quick start"),
    ("examples/toc_example.py", "table-of-contents", "Table of contents"),
    ("examples/data_tables_example.py", "tables-from-data", "Tables from data"),
    ("examples/table_styling_example.py", "table-styling", "Table styling"),
    ("examples/figures_example.py", "figures", "Figures and cross-references"),
    ("examples/callouts_example.py", "callouts-and-inline-styles", "Callouts and inline styles"),
    ("examples/lists_example.py", "lists-and-page-breaks", "Lists and page breaks"),
    ("examples/pages_example.py", "headers-footers-numbering", "Headers, footers and section numbering"),
    ("examples/cover_example.py", "cover-page", "Cover page"),
    ("examples/merge_example.py", "merging-and-highlighting", "Merging, metadata and highlighting"),
]

FORMATS = [(".html", "HTML"), (".pdf", "PDF"), (".md", "Markdown"), (".tex", "LaTeX")]


def summary(script: Path) -> str:
    """First sentence of the example's docstring, without the "Demo:" prefix."""
    doc = ast.get_docstring(ast.parse(script.read_text(encoding="utf-8"))) or script.stem
    first = " ".join(doc.split("\n\n")[0].split())
    return first.removeprefix("Demo: ").rstrip(".")


def run_example(script: str, workdir: Path) -> Path:
    """Run one example in a fresh copy of the examples; return its output folder."""
    shutil.copytree(ROOT / "examples", workdir / "examples", ignore=shutil.ignore_patterns("output"))
    shutil.copy2(ROOT / "example.py", workdir / "example.py")
    # Import this checkout's reportsmith, whether or not it is installed.
    pythonpath = os.pathsep.join(p for p in (str(ROOT), os.environ.get("PYTHONPATH", "")) if p)
    env = {**os.environ, "MPLBACKEND": "Agg", "PYTHONIOENCODING": "utf-8", "PYTHONPATH": pythonpath}
    # The quick-start example writes next to the working directory; the
    # others write to examples/output.
    subprocess.run([sys.executable, str(workdir / script)], cwd=workdir, env=env, check=True)
    return workdir if script == "example.py" else workdir / "examples" / "output"


def collect(output: Path, destination: Path) -> dict[str, list[Path]]:
    """Copy an example's generated files; map each base name to its files."""
    reports: dict[str, list[Path]] = {}
    for path in sorted(output.iterdir()):
        if path.is_dir() and path.name.endswith("_files"):
            shutil.copytree(path, destination / path.name)
        elif path.suffix in {suffix for suffix, _ in FORMATS}:
            shutil.copy2(path, destination / path.name)
            reports.setdefault(path.stem, []).append(destination / path.name)
    return reports


def build(site: Path) -> None:
    from reportsmith import Report, code, link

    if site.exists():
        shutil.rmtree(site)
    site.mkdir(parents=True)
    (site / ".nojekyll").write_text("")  # serve folders as they are

    import reportsmith

    index = Report(
        "reportsmith examples",
        subtitle="Reports built with reportsmith, exported to HTML, PDF, Markdown and LaTeX",
        date="",
        description="Example reports built with the reportsmith Python library",
        keywords=["reportsmith", "python", "reports", "examples"],
        footer=None,
    )
    index.paragraph(
        [
            "Every report below is generated by a short Python script using ",
            link("reportsmith", REPO_URL), f" {reportsmith.__version__}. "
            "Open a format to see the output, or the source to see how it was made. "
            "The pages are rebuilt from the latest code on every change.",
        ]
    )
    index.toc(title="Examples", depth=1)

    with tempfile.TemporaryDirectory() as tmp:
        for script, slug, title in EXAMPLES:
            print(f"Building {slug} ({script})", flush=True)
            destination = site / slug
            destination.mkdir()
            output = run_example(script, Path(tmp) / slug)
            reports = collect(output, destination)
            shutil.copy2(ROOT / script, destination / "source.py")

            with index.section(title) as s:
                description = summary(ROOT / script)
                s.paragraph(description[0].upper() + description[1:] + ".")
                for stem, files in reports.items():
                    by_suffix = {f.suffix: f for f in files}
                    links: list = []
                    for suffix, label in FORMATS:
                        if suffix in by_suffix:
                            if links:
                                links.append(" · ")
                            links.append(link(label, f"{slug}/{by_suffix[suffix].name}"))
                    if len(reports) > 1:
                        links = [code(stem), ": "] + links
                    s.paragraph(links)
                s.paragraph(
                    [
                        "Source: ", link(Path(script).name, f"{slug}/source.py"),
                        " (", link("on GitHub", f"{REPO_URL}/blob/main/{script}"), ")",
                    ]
                )

    index.paragraph(
        [
            "Run any example locally with ",
            code("python examples/<name>.py"),
            " after ",
            code("pip install reportsmith[pdf,highlight] pandas matplotlib"),
            ".",
        ]
    )
    index.save_html(site / "index.html")
    print(f"Site written to {site}")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    build(Path(sys.argv[1]).resolve())
